entries[16058] = { ["name"] = "Fordrings Siegel", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+4 Ausdauer\n+5 Intelligenz\nAnlegen: Erhöht die Zaubermacht um 20." }
