entries[16084] = { ["name"] = "Erste Hilfe für Experten - Verbinden, aber richtig", ["text"] = "Benötigt Erste Hilfe (125)\nBenutzen: Lehrt Euch, ein Experte für Erste Hilfe mit einer maximalen Fertigkeit von 225 zu werden." }
entries[16085] = { ["name"] = "Erste Hilfe für den Fachmann - Heilt Euch selbst", ["text"] = "Benötigt Erste Hilfe (200)\nBenutzen: Lehrt Euch hochentwickelte Erste Hilfe mit einer maximalen Fertigkeit von 300." }
entries[16110] = { ["name"] = "Rezept: Monsteromelett", ["text"] = "Benötigt Kochkunst (225)\nBenutzen: Lehrt Euch, wie man ein Monsteromelett zubereitet.\nMonsteromelett\nBenötigt Stufe 40\nBenutzen: Stellt im Verlauf von 30 sec 1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 12 Ausdauer und Willenskraft.\nBenötigt Riesenei" }
entries[16111] = { ["name"] = "Rezept: Gewürzter Chilikrebs", ["text"] = "Benötigt Kochkunst (225)\nBenutzen: Lehrt Euch, wie man gewürzten Chilikrebs zubereitet.\nGewürzter Chilikrebs\nBenötigt Stufe 40\nBenutzen: Stellt im Verlauf von 30 sec 1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 12 Ausdauer und Willenskraft.\nBenötigt Zartes Krebsfleisch" }
