entries[16221] = { ["name"] = "Formel: Brust - Erhebliche Gesundheit", ["text"] = "Benötigt Verzauberkunst (275)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft zu verzaubern, sodass sie die Gesundheit um 100 erhöhen.\nEine Brustrüstung dauerhaft verzaubern, sodass die Gesundheit um 100 erhöht wird." }
entries[16222] = { ["name"] = "Formel: Schild - Erhebliche Willenskraft", ["text"] = "Benötigt Verzauberkunst (280)\nBenutzen: Lehrt Euch, Schilde dauerhaft zu verzaubern, sodass sie die Willenskraft um 9 erhöhen.\nEinen Schild dauerhaft verzaubern, sodass alle 5 Sek. 4 Mana und Gesundheit wiederhergestellt werden." }
entries[16223] = { ["name"] = "Formel: Waffe - Eisiger Hauch", ["text"] = "Benötigt Verzauberkunst (285)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie den Getroffenen oft unterkühlen und sein Bewegungs- und Angriffstempo verringern. Verringerter Effekt bei Spielern über Stufe 60.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass das Ziel oft unterkühlt und somit sein Bewegungs- und Angriffstempo verringert wird. Verringerter Effekt bei Charakteren über Stufe 60." }
entries[16224] = { ["name"] = "Formel: Umhang - Überragende Verteidigung", ["text"] = "Benötigt Verzauberkunst (285)\nBenutzen: Lehrt Euch, Umhänge dauerhaft zu verzaubern, sodass sie die Rüstung um 70 erhöhen.\nEinen Umhang dauerhaft verzaubern, sodass die Rüstung um 70 erhöht wird." }
entries[16242] = { ["name"] = "Formel: Brust - Erhebliches Mana", ["text"] = "Benötigt Verzauberkunst (290)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft zu verzaubern, sodass sie das Mana um 100 erhöhen.\nEine Brustrüstung dauerhaft verzaubern, sodass das Mana um 100 erhöht wird." }
entries[16243] = { ["name"] = "Formel: Runenverzierte Arkanitrute", ["text"] = "Benötigt Verzauberkunst (290)\nBenutzen: Lehrt Euch die Herstellung einer runenverzierten Arkanitrute.\nRunenverzierte Arkanitrute\nWird beim Aufheben gebunden\n\"Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"\nBenötigt Arkanitrute , Goldene Perle , Illusionsstaub (10), Große ewige Essenz (4), Runenverzierte Echtsilberrute , Großer glänzender Splitter (2)" }
entries[16244] = { ["name"] = "Formel: Handschuhe - Große Stärke", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Handschuhe dauerhaft zu verzaubern, sodass sie die Stärke um 7 erhöhen.\nHandschuhe dauerhaft verzaubern, sodass die Stärke um 7 erhöht wird." }
