entries[16247] = { ["name"] = "Formel: Zweihandwaffe - Überragender Einschlag", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft zu verzaubern, sodass ihr Schaden um 9 erhöht wird.\nEine Zweihandwaffe dauerhaft verzaubern, sodass ihr Schaden um 9 erhöht wird." }
entries[16248] = { ["name"] = "Formel: Waffe - Unheilig", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie den Getroffenen oft mit einem Fluch belegen, der Schattenschaden verursacht und den Nahkampfschaden verringert.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie den Getroffenen oft mit einem Fluch belegt, der Schattenschaden verursacht und seinen Nahkampfschaden verringert." }
entries[16249] = { ["name"] = "Formel: Zweihandwaffe - Erhebliche Intelligenz", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft zu verzaubern, sodass sie die Intelligenz um 9 erhöhen.\nEine Zweihandwaffe dauerhaft verzaubern, sodass die Intelligenz um 9 erhöht wird." }
entries[16250] = { ["name"] = "Formel: Waffe - Überragendes Schlagen", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass ihr Schaden um 5 erhöht wird.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass ihr Schaden um 5 erhöht wird." }
entries[16251] = { ["name"] = "Formel: Armschiene - Überragende Ausdauer", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass sie die Ausdauer um 9 erhöhen.\nArmschienen dauerhaft verzaubern, sodass die Ausdauer um 9 erhöht wird." }
entries[16252] = { ["name"] = "Formel: Waffe - Kreuzfahrer", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie ihren Träger oft um 75 bis 125 heilt und die Stärke 15 Sek. lang um 100 erhöht, wenn ein Nahkampfangriff durchgeführt wird. Verringerter Effekt bei Spielern über Stufe 60.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie ihren Träger oft um 75 bis 125 heilt und die Stärke 15 Sek. lang um 100 erhöht, wenn ein Nahkampfangriff durchgeführt wird. Verringerter Effekt bei Charakteren über Stufe 60." }
entries[16253] = { ["name"] = "Formel: Brust - Große Werte", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft zu verzaubern, sodass sie alle Werte um 4 erhöhen.\nEine Brustrüstung dauerhaft verzaubern, sodass alle Werte um 4 erhöht werden." }
entries[16254] = { ["name"] = "Formel: Waffe - Lebensdiebstahl", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie oft vom Getroffenen Leben stehlen und auf ihren Träger übertragen. Verringerter Effekt bei Spielern über Stufe 60.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass vom Feind oft Leben gestohlen und auf den Benutzer übertragen wird. Verringerter Effekt bei Charakteren über Stufe 60." }
